function adToCell(ad) {
  const title = (ad.title || '').trim();
  const date = ad.ts ? new Date(ad.ts * 1000).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '';
  const label = (title && title !== 'instagram.com') ? `${title} (${date})` : `View Ad (${date})`;
  return `=HYPERLINK("${ad.url}","${label.replace(/"/g, "'")}")`;
}

async function main() {
  const key = JSON.parse(fs.readFileSync(KEY_FILE, 'utf8'));

  const auth = new google.auth.GoogleAuth({
    credentials: key,
    scopes: ['https://www.googleapis.com/auth/spreadsheets'],
  });

  const sheets = google.sheets({ version: 'v4', auth });

  // First clear rows 3+ so we have a clean slate
  await sheets.spreadsheets.values.clear({
    spreadsheetId: SHEET_ID,
    range: 'Intel!A3:M1000',
  });
  console.log('Cleared existing data rows');

  // Brand columns: SB=B, Mars=D, Renee=F, Sugar=H, May=J, Insight=L
  const brands = [
    { col: 'B', ads: swissBeautyAds,  name: 'Swiss Beauty' },
    { col: 'D', ads: marsAds,          name: 'Mars Cosmetics' },
    { col: 'F', ads: reneeAds,         name: 'Renee Cosmetics' },
    { col: 'H', ads: sugarAds,         name: 'SUGAR Cosmetics' },
    { col: 'J', ads: maybellineAds,    name: 'Maybelline' },
    { col: 'L', ads: insightAds,       name: 'Insight Cosmetics' },
  ];

  for (const brand of brands) {
    const values = brand.ads.map(ad => [adToCell(ad)]);
    const startRow = 3;
    const endRow = startRow + values.length - 1;
    const range = `Intel!${brand.col}${startRow}:${brand.col}${endRow}`;

    await sheets.spreadsheets.values.update({
      spreadsheetId: SHEET_ID,
      range,
      valueInputOption: 'USER_ENTERED',
      requestBody: { values },
    });
    console.log(`Wrote ${values.length} ads for ${brand.name} to column ${brand.col}`);
  }

  console.log('\nDone! Sheet populated with all brand ads.');
}

main().catch(e => { console.error(e.message || e); process.exit(1); });
